let currentLanguage = getInitialPrivacyLanguage();

function getInitialPrivacyLanguage() {
  const hashLanguage = window.location.hash.replace("#", "");
  if (hashLanguage === "de" || hashLanguage === "en") return hashLanguage;
  return document.documentElement.lang === "de" ? "de" : "en";
}

function selectElement(selector) {
  return document.querySelector(selector);
}

function selectAllElements(selector) {
  return Array.from(document.querySelectorAll(selector));
}

function getTranslations() {
  return privacyPageTranslations[currentLanguage] || privacyPageTranslations.en;
}

function isMobileMenuOpen() {
  return document.body.classList.contains("mobile-menu-open");
}

function updateLanguageSwitchImage(isHovering = false) {
  const image = selectElement(".site-header__lang-switch");
  const imageSets = {
    en: {
      default: "../assets/imgs/Header/Language_switch.png",
      hover: "../assets/imgs/Header/Property 1=Default hover.png"
    },
    de: {
      default: "../assets/imgs/Header/Property 1=Deutsch.png",
      hover: "../assets/imgs/Header/Property 1=Deutsch hover.png"
    }
  };
  const imageSet = imageSets[currentLanguage];
  if (!image || !imageSet) return;
  image.src = isHovering ? imageSet.hover : imageSet.default;
}

function setElementAttribute(selector, attribute, value) {
  const element = selectElement(selector);
  if (element) element.setAttribute(attribute, value);
}

function refreshMobileMenuLabel() {
  const menuButton = selectElement(".site-header__menu-toggle");
  const translations = getTranslations();
  if (!menuButton) return;
  menuButton.setAttribute("aria-label", isMobileMenuOpen() ? translations.mobileMenu.close : translations.mobileMenu.open);
}

function setMobileMenuState(isOpen) {
  const menuButton = selectElement(".site-header__menu-toggle");
  document.body.classList.toggle("mobile-menu-open", isOpen);
  if (menuButton) menuButton.setAttribute("aria-expanded", String(isOpen));
  refreshMobileMenuLabel();
}

function closeMobileMenu() {
  setMobileMenuState(false);
}

function toggleMobileMenu() {
  setMobileMenuState(!isMobileMenuOpen());
}

function applyLanguageButton(translations) {
  const languageButton = selectElement(".site-header__lang-button");
  if (!languageButton) return;
  languageButton.setAttribute("aria-label", translations.header.switchLabel);
  languageButton.setAttribute("aria-pressed", currentLanguage === "de" ? "true" : "false");
  updateLanguageSwitchImage(false);
}

function applyHeaderTexts(translations) {
  document.documentElement.lang = translations.lang;
  setElementAttribute(".site-header__nav", "aria-label", translations.header.navLabel);
  setElementAttribute('.site-header__link[href="#about"]', "aria-label", translations.header.about);
  setElementAttribute('.site-header__link[href="#skills"]', "aria-label", translations.header.skills);
  setElementAttribute('.site-header__link[href="#projects"]', "aria-label", translations.header.projects);
  setElementAttribute(".site-header__logo", "aria-label", translations.header.logoLabel);
  applyLanguageButton(translations);
  refreshMobileMenuLabel();
}

function applyFooterMetaTexts(metaTexts) {
  const footerMetaItems = selectAllElements(".site-footer__meta span");
  metaTexts.forEach((text, index) => {
    if (footerMetaItems[index]) footerMetaItems[index].textContent = text;
  });
}

function applyFooterLinkTexts(linkTexts) {
  const footerLinks = selectAllElements(".site-footer__nav a");
  linkTexts.forEach((text, index) => {
    if (footerLinks[index]) footerLinks[index].textContent = text;
  });
}

function applyFooterTexts(translations) {
  setElementAttribute(".site-footer__brand", "aria-label", translations.footer.brandLabel);
  setElementAttribute(".site-footer__nav", "aria-label", translations.footer.navLabel);
  applyFooterMetaTexts(translations.footer.meta);
  applyFooterLinkTexts(translations.footer.links);
}

function applyPrivacyTexts(translations) {
  const title = selectElement("#privacyNoticeTitle");
  const content = selectElement("#privacyNoticeContent");
  document.title = `${translations.privacy.title} | Florian Narr`;
  if (title) title.textContent = translations.privacy.title;
  if (content) content.innerHTML = translations.privacy.content;
  setElementAttribute(".legal-page__back", "aria-label", translations.privacy.backLabel);
}

function applyPageLanguage(language) {
  currentLanguage = language;
  const translations = getTranslations();
  applyHeaderTexts(translations);
  applyFooterTexts(translations);
  applyPrivacyTexts(translations);
  history.replaceState(null, "", `#${language}`);
}

function handleLanguageButtonClick() {
  const nextLanguage = currentLanguage === "de" ? "en" : "de";
  applyPageLanguage(nextLanguage);
}

function registerLanguageButtonEvents() {
  const button = selectElement(".site-header__lang-button");
  if (!button) return;
  button.addEventListener("click", handleLanguageButtonClick);
  button.addEventListener("mouseenter", () => updateLanguageSwitchImage(true));
  button.addEventListener("mouseleave", () => updateLanguageSwitchImage(false));
  button.addEventListener("focus", () => updateLanguageSwitchImage(true));
  button.addEventListener("blur", () => updateLanguageSwitchImage(false));
}

function isMobileMenuOutsideClick(event, mobileMenu, menuButton) {
  if (!isMobileMenuOpen()) return false;
  if (!(event.target instanceof Element)) return false;
  const clickedInsideMenu = mobileMenu.contains(event.target);
  const clickedMenuButton = menuButton.contains(event.target);
  return !clickedInsideMenu && !clickedMenuButton;
}

function registerMobileMenuLinks(mobileMenu) {
  mobileMenu.querySelectorAll("a").forEach((link) => {
    link.addEventListener("click", closeMobileMenu);
  });
}

function handleMobileMenuResize() {
  if (window.innerWidth > 768) closeMobileMenu();
}

function handleMobileMenuKeydown(event) {
  if (event.key === "Escape") closeMobileMenu();
}

function registerMobileMenuGlobalEvents(mobileMenu, menuButton) {
  window.addEventListener("resize", handleMobileMenuResize);
  document.addEventListener("keydown", handleMobileMenuKeydown);
  document.addEventListener("click", (event) => {
    if (isMobileMenuOutsideClick(event, mobileMenu, menuButton)) closeMobileMenu();
  });
}

function registerMobileMenuEvents() {
  const menuButton = selectElement(".site-header__menu-toggle");
  const mobileMenu = selectElement("#siteHeaderMobileMenu");
  if (!menuButton || !mobileMenu) return;
  menuButton.addEventListener("click", toggleMobileMenu);
  registerMobileMenuLinks(mobileMenu);
  registerMobileMenuGlobalEvents(mobileMenu, menuButton);
}

function getLocalHashTarget(link) {
  const hash = link.getAttribute("href");
  if (!hash || hash.length <= 1) return null;
  return hash;
}

function handleMissingHashLinkClick(event) {
  const link = event.target.closest('a[href^="#"]');
  if (!link) return;
  const hash = getLocalHashTarget(link);
  if (!hash || hash === "#en" || hash === "#de" || document.querySelector(hash)) return;
  event.preventDefault();
  window.location.href = `../index.html${hash}`;
}

function redirectHashLinksToIndex() {
  document.addEventListener("click", handleMissingHashLinkClick);
}

function initializePrivacyPage() {
  applyPageLanguage(currentLanguage);
  registerLanguageButtonEvents();
  registerMobileMenuEvents();
  redirectHashLinksToIndex();
}

initializePrivacyPage();